bu kod segmentation fault veriyo nerde hata bulamadım, veri yapıları ödevi
#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int data; struct Node* next; } Node;

void ekle(Node* head, int x) {
    Node* yeni = malloc(sizeof(Node));
    yeni->data = x;
    yeni->next = NULL;
    if (head == NULL) { head = yeni; return; }
    Node* t = head;
    while (t->next != NULL) t = t->next;
    t->next = yeni;
}

int main() {
    Node* head = NULL;
    ekle(head, 5); ekle(head, 8);
    printf("%d
", head->data);
    return 0;
}

