import { useState, useEffect } from 'react';
import axios from 'axios';

export default function NotTablosu({ dersId }) {
  const [notlar, setNotlar] = useState([]);
  const [filtre, setFiltre] = useState({ donem: 'guz', sadeceKalanlar: false });
  const [ortalama, setOrtalama] = useState(0);

  useEffect(() => {
    axios.get(`/api/dersler/${dersId}/notlar`, { params: filtre })
      .then(res => {
        setNotlar(res.data);
        setFiltre({ ...filtre, sonGuncelleme: Date.now() });
      });
  }, [filtre]);

  useEffect(() => {
    const top = notlar.reduce((a, n) => a + n.puan, 0);
    setOrtalama(top / notlar.length);
  });

  return (
    <div>
      <p>Ortalama: {ortalama.toFixed(1)}</p>
      <table>
        {notlar.map(n => <tr><td>{n.ogrenci}</td><td>{n.puan}</td></tr>)}
      </table>
    </div>
  );
}

