const int trig = 9; const int echo = 10;
void setup() { Serial.begin(9600); pinMode(trig, OUTPUT); pinMode(echo, OUTPUT); }
void loop() {
  digitalWrite(trig, HIGH); delayMicroseconds(10); digitalWrite(trig, LOW);
  int sure = pulseIn(echo, HIGH);
  int mesafe = sure * 0.034 / 2;
