this component keeps re-fetching in an infinite loop and my browser tab freezes. i'm mostly a backend dev, what am i doing wrong?

import { useEffect, useState } from "react";

export default function ShiftList({ wardId }) {
  const [shifts, setShifts] = useState([]);
  const [filters, setFilters] = useState({ week: 46, onlyNight: false });
  const [loading, setLoading] = useState(false);

  const params = { ward: wardId, ...filters };

  useEffect(() => {
    setLoading(true);
    fetch("/api/shifts?" + new URLSearchParams(params))
      .then(r => r.json())
      .then(data => {
        setShifts(data);
        setLoading(false);
      });
  }, [params]);

  return (
    <div>
      <label>
        <input type="checkbox" checked={filters.onlyNight}
          onChange={e => setFilters({ ...filters, onlyNight: e.target.checked })} />
        night only
      </label>
      {loading ? <p>loading...</p> : (
        <ul>{shifts.map(s => <li key={s.id}>{s.nurse} – {s.date} – {s.type}</li>)}</ul>
      )}
    </div>
  );
}

console shows hundreds of GET /api/shifts?ward=3&week=46&onlyNight=false per second. no error message, just the loop. also sometimes i see "Warning: Can't perform a React state update on an unmounted component" when i switch pages quickly. react 18, no extra libraries. would be nice if you can also tell me the proper way to cancel the request

