spring boot projesinde sipariş oluştururken NPE alıyorum, lokalde çalışıyo test ortamında patlıyo. şuna bi bakar mısın

@Service
public class OrderService {

    @Autowired
    private DiscountClient discountClient;

    private final OrderRepository repo;

    public OrderService(OrderRepository repo) {
        this.repo = repo;
    }

    public Order create(OrderRequest req) {
        Discount d = discountClient.getFor(req.getCustomerId());
        BigDecimal total = req.getTotal().multiply(BigDecimal.ONE.subtract(d.getRate()));
        Order o = new Order(req.getCustomerId(), total);
        return repo.save(o);
    }
}

java.lang.NullPointerException: Cannot invoke "com.shop.discount.Discount.getRate()" because "d" is null
    at com.shop.order.OrderService.create(OrderService.java:17)
    at com.shop.order.OrderController.create(OrderController.java:31)
    at java.base/jdk.internal.reflect.DirectMethodHandleAccessor.invoke(DirectMethodHandleAccessor.java:103)
    at org.springframework.web.method.support.InvocableHandlerMethod.doInvoke(InvocableHandlerMethod.java:255)
    at org.springframework.web.servlet.FrameworkServlet.service(FrameworkServlet.java:885)

